def _parse_in_tail(self, operand: tuple) -> tuple:
    # An optional "[NOT] IN (option, ...)" predicate; IN stays an
    # ordinary identifier elsewhere, so a column spelled "in" keeps
    # working outside this position.
    negated = False
    if self._accept_keyword("not"):
        negated = True
    if self._accept_word("in"):
        options = self._parse_in_options()
        return ("in", operand, options, negated)
    if negated:
        # A stray NOT that does not introduce a predicate is invalid:
        # "NOT IN" without its list or NOT before a non-IN token here.
        tok = self._peek()
        raise QuerySyntaxError(
            f"expected IN after NOT, got {tok.text!r}"
        )
    return operand

